-- Designvorschlag PostgreSQL 16+, noch NICHT mit produktiver Datenbank verbunden.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE branches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true);
CREATE TABLE app_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, display_name text NOT NULL, password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (user_id uuid NOT NULL REFERENCES app_users(id), branch_id uuid NOT NULL REFERENCES branches(id), role text NOT NULL CHECK(role IN ('system_admin','operations_manager','branch_manager','trainer','employee','auditor')), PRIMARY KEY(user_id,branch_id,role));
CREATE TABLE media_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), storage_key text NOT NULL UNIQUE, mime_type text NOT NULL, original_name text NOT NULL, uploaded_by uuid NOT NULL REFERENCES app_users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sop_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, title text NOT NULL, category text NOT NULL);
CREATE TABLE sop_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sop_id uuid NOT NULL REFERENCES sop_documents(id), version_no integer NOT NULL CHECK(version_no>0), status text NOT NULL CHECK(status IN ('draft','review','approved','archived')), body jsonb NOT NULL, approved_by uuid REFERENCES app_users(id), approved_at timestamptz, UNIQUE(sop_id,version_no), CHECK ((status <> 'approved') OR (approved_by IS NOT NULL AND approved_at IS NOT NULL)));
CREATE TABLE task_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), branch_id uuid NOT NULL REFERENCES branches(id), title text NOT NULL, recurrence_rule text, sop_version_id uuid REFERENCES sop_versions(id), active boolean NOT NULL DEFAULT true);
CREATE TABLE task_occurrences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), template_id uuid NOT NULL REFERENCES task_templates(id), due_at timestamptz NOT NULL, assigned_to uuid REFERENCES app_users(id), completed_by uuid REFERENCES app_users(id), completed_at timestamptz, status text NOT NULL CHECK(status IN ('open','in_progress','completed','overdue','blocked')) DEFAULT 'open', notes text);
CREATE TABLE task_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid NOT NULL REFERENCES task_occurrences(id), media_id uuid REFERENCES media_assets(id), note text, created_by uuid NOT NULL REFERENCES app_users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE equipment (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), branch_id uuid NOT NULL REFERENCES branches(id), name text NOT NULL, manufacturer text, model text, serial_number text, manual_media_id uuid REFERENCES media_assets(id), status text NOT NULL DEFAULT 'active');
CREATE TABLE haccp_monitoring_points (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), branch_id uuid NOT NULL REFERENCES branches(id), name text NOT NULL, unit text NOT NULL, lower_limit numeric, upper_limit numeric, approved_sop_version_id uuid REFERENCES sop_versions(id));
CREATE TABLE haccp_measurements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), point_id uuid NOT NULL REFERENCES haccp_monitoring_points(id), measured_value numeric NOT NULL, measured_at timestamptz NOT NULL DEFAULT now(), recorded_by uuid NOT NULL REFERENCES app_users(id), note text);
CREATE TABLE deviations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), branch_id uuid NOT NULL REFERENCES branches(id), measurement_id uuid REFERENCES haccp_measurements(id), description text NOT NULL, status text NOT NULL DEFAULT 'open', reported_by uuid NOT NULL REFERENCES app_users(id), reported_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE corrective_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), deviation_id uuid NOT NULL REFERENCES deviations(id), action_text text NOT NULL, taken_by uuid NOT NULL REFERENCES app_users(id), taken_at timestamptz NOT NULL DEFAULT now(), verified_by uuid REFERENCES app_users(id), verified_at timestamptz);
CREATE TABLE inventory_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sku text NOT NULL UNIQUE, name text NOT NULL, base_unit text NOT NULL, min_quantity numeric NOT NULL DEFAULT 0);
CREATE TABLE storage_locations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), branch_id uuid NOT NULL REFERENCES branches(id), name text NOT NULL, UNIQUE(branch_id,name));
CREATE TABLE stock_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item_id uuid NOT NULL REFERENCES inventory_items(id), location_id uuid NOT NULL REFERENCES storage_locations(id), quantity_delta numeric NOT NULL CHECK(quantity_delta<>0), movement_type text NOT NULL CHECK(movement_type IN ('receipt','consumption','waste','transfer','adjustment')), reason text, performed_by uuid NOT NULL REFERENCES app_users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE stock_counts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), location_id uuid NOT NULL REFERENCES storage_locations(id), status text NOT NULL DEFAULT 'draft', counted_by uuid NOT NULL REFERENCES app_users(id), counted_at timestamptz);
CREATE TABLE stock_count_lines (count_id uuid NOT NULL REFERENCES stock_counts(id), item_id uuid NOT NULL REFERENCES inventory_items(id), counted_quantity numeric NOT NULL CHECK(counted_quantity>=0), PRIMARY KEY(count_id,item_id));
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES app_users(id), branch_id uuid REFERENCES branches(id), entity_type text NOT NULL, entity_id uuid NOT NULL, action text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON task_occurrences(due_at,status);
CREATE INDEX ON haccp_measurements(point_id,measured_at DESC);
CREATE INDEX ON stock_movements(item_id,location_id,created_at DESC);
CREATE INDEX ON audit_events(entity_type,entity_id,occurred_at DESC);
